-- INWP organizational directory (PostgreSQL 13+)
-- Apply in order. Uses UUIDs generated by PostgreSQL; contains no production data.
BEGIN;

CREATE SCHEMA org;

CREATE TABLE org.organizations (
    id              UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    parent_id       UUID REFERENCES org.organizations(id) ON DELETE RESTRICT,
    code            TEXT NOT NULL CHECK (code = btrim(code) AND length(code) BETWEEN 1 AND 64),
    name            TEXT NOT NULL CHECK (name = btrim(name) AND length(name) BETWEEN 1 AND 240),
    status          TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'inactive')),
    valid_from      DATE NOT NULL DEFAULT CURRENT_DATE,
    valid_to        DATE,
    version         BIGINT NOT NULL DEFAULT 1 CHECK (version > 0),
    created_at      TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at      TIMESTAMPTZ NOT NULL DEFAULT now(),
    created_by      UUID,
    updated_by      UUID,
    CONSTRAINT organizations_validity CHECK (valid_to IS NULL OR valid_to > valid_from),
    CONSTRAINT organizations_not_own_parent CHECK (parent_id IS NULL OR parent_id <> id),
    CONSTRAINT organizations_id_parent_key UNIQUE (id, parent_id)
);

CREATE UNIQUE INDEX organizations_root_code_uq
    ON org.organizations (code) WHERE parent_id IS NULL;
CREATE UNIQUE INDEX organizations_child_code_uq
    ON org.organizations (parent_id, code) WHERE parent_id IS NOT NULL;
CREATE INDEX organizations_parent_idx ON org.organizations (parent_id);

CREATE TABLE org.units (
    id              UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    organization_id UUID NOT NULL REFERENCES org.organizations(id) ON DELETE RESTRICT,
    parent_unit_id  UUID,
    code            TEXT NOT NULL CHECK (code = btrim(code) AND length(code) BETWEEN 1 AND 64),
    name            TEXT NOT NULL CHECK (name = btrim(name) AND length(name) BETWEEN 1 AND 240),
    status          TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'inactive')),
    valid_from      DATE NOT NULL DEFAULT CURRENT_DATE,
    valid_to        DATE,
    version         BIGINT NOT NULL DEFAULT 1 CHECK (version > 0),
    created_at      TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at      TIMESTAMPTZ NOT NULL DEFAULT now(),
    created_by      UUID,
    updated_by      UUID,
    CONSTRAINT units_validity CHECK (valid_to IS NULL OR valid_to > valid_from),
    CONSTRAINT units_not_own_parent CHECK (parent_unit_id IS NULL OR parent_unit_id <> id),
    CONSTRAINT units_id_org_key UNIQUE (id, organization_id),
    CONSTRAINT units_parent_same_org_fk FOREIGN KEY (parent_unit_id, organization_id)
        REFERENCES org.units(id, organization_id) ON DELETE RESTRICT,
    CONSTRAINT units_org_code_uq UNIQUE (organization_id, code)
);
CREATE INDEX units_parent_idx ON org.units (parent_unit_id);
CREATE INDEX units_org_status_idx ON org.units (organization_id, status);

CREATE TABLE org.sites (
    id              UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    organization_id UUID NOT NULL REFERENCES org.organizations(id) ON DELETE RESTRICT,
    unit_id         UUID NOT NULL,
    code            TEXT NOT NULL CHECK (code = btrim(code) AND length(code) BETWEEN 1 AND 64),
    name            TEXT NOT NULL CHECK (name = btrim(name) AND length(name) BETWEEN 1 AND 240),
    status          TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'inactive')),
    valid_from      DATE NOT NULL DEFAULT CURRENT_DATE,
    valid_to        DATE,
    version         BIGINT NOT NULL DEFAULT 1 CHECK (version > 0),
    created_at      TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at      TIMESTAMPTZ NOT NULL DEFAULT now(),
    created_by      UUID,
    updated_by      UUID,
    CONSTRAINT sites_validity CHECK (valid_to IS NULL OR valid_to > valid_from),
    CONSTRAINT sites_id_unit_key UNIQUE (id, unit_id),
    CONSTRAINT sites_unit_org_fk FOREIGN KEY (unit_id, organization_id)
        REFERENCES org.units(id, organization_id) ON DELETE RESTRICT,
    CONSTRAINT sites_unit_code_uq UNIQUE (unit_id, code)
);
CREATE INDEX sites_org_status_idx ON org.sites (organization_id, status);
CREATE INDEX sites_unit_status_idx ON org.sites (unit_id, status);

COMMENT ON SCHEMA org IS 'Authoritative organizational hierarchy; changes should be effective-dated and audited.';
COMMENT ON TABLE org.organizations IS 'Top-level organizational entities. Physical deletion is restricted by references.';
COMMENT ON TABLE org.units IS 'Units belong to one organization; parent units must belong to the same organization.';
COMMENT ON TABLE org.sites IS 'Work locations belong to one unit and organization.';

COMMIT;
